"""Summarise reports/checks_*.json + step_validation.json into reports/CHECKS.md"""
import json, os
import ct72_params as P
R = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "reports")
L = ["# CT72 rev A1 - interference + envelope/reach checks", "",
     "Generated by `cad/checks.py` (OCP boolean intersections; volume > 1 mm^3 = clash; touching faces = 0).",
     "Gantry states checked: PARK (back-right, raised) + all 8 travel corners; moving hardware is also swept over its full travel as a box (conservative).", "",
     f"Travel: bridge X {P.GX_MIN:.0f}-{P.GX_MAX:.0f} mm, carriage Y {P.GY_MIN:.0f}-{P.GY_MAX:.0f} mm, arm-plate underside Z {P.PZ_MIN:.0f}-{P.PZ_MAX:.0f} mm "
     f"(Z travel {P.Z_TRAVEL:.0f} mm = {P.Z_TRAVEL/25.4:.1f} in). Arm base sits {abs(P.ARM_BASE_X_OFF):.0f} mm -X of the bridge.", ""]
for t in P.TIERS:
    r = json.load(open(os.path.join(R, f"checks_{t}.json")))
    hard = [x for x in r["moving_vs_static"] if x[3] == "HARD"]
    cond = [x for x in r["moving_vs_static"] if x[3] != "HARD"]
    L += [f"## {t.upper()} ({r['arm_pose']['arm']})", "",
          f"- Static hardware vs static hardware: **{len(r['static_pairs'])} clashes**",
          f"- Moving gantry hardware (swept full travel) vs static: **{len(hard)} hard clashes**; {len(cond)} conditional (" +
          ", ".join(f"{a} vs {b}" for a, b, *_ in cond) + ") - deployable roosts, allowed only when PARKED (brief 2.4)",
          f"- Moving parts vs each other at 9 states: **{len(r['moving_internal'])} clashes**",
          "- Keepout rules:"]
    for k in r["keepout_rules"]:
        L.append(f"  - {'PASS' if k['pass'] else 'FAIL'} - {k['rule']}" + (f" ({k['note']})" if k['note'] else ""))
    a = r["arm_pose"]; rr = r["reach"]
    L += [f"- Arm hanging length (straight reference pose): {a['hanging_length_mm']} mm; straight pose stays above BED_KEEPOUT only with plate >= {a['min_plate_z_straight_pose_above_BED_KEEPOUT_mm']} mm (travel goes down to {a['plate_z_travel_mm'][0]} mm) -> below that the arm must be folded / Z-limited in software.",
          f"- Reach {rr['reach_mm']} mm: SAFE-footprint coverage at PLANE_ROBOT_Z0 = **{rr['coverage_pct_SAFE_footprint_at_PLANE_ROBOT_Z0']}%**, at PLANE_ROBOT_TOP = {rr['coverage_pct_SAFE_footprint_at_PLANE_ROBOT_TOP']}%",
          f"- Reach envelope overshoots the inner frame faces by {rr['overreach_past_inner_frame_mm']} mm and the 72x72 outer footprint by {rr['overreach_past_72x72_footprint_mm']} mm -> needs {'UR safety planes (safety-rated)' if t == 'pro' else 'firmware zone limits (not safety-rated; guarding is the protection)'} at the guard faces."]
    if t == "starter":
        L.append(f"- No-arm Starter (fixed tool, {P.STARTER_TOOL_DROP/25.4:.0f} in drop): tool point reaches z={rr['no_arm_tool_point_lowest_z_mm']} mm (PLANE_ROBOT_Z0 {P.PLANE_ROBOT_Z0:.0f}: {'OK' if rr['no_arm_tool_reaches_PLANE_ROBOT_Z0'] else 'NO'}); XY coverage of SAFE footprint {rr['no_arm_coverage_pct_SAFE_footprint']}%.")
    if t == "pro":
        L.append(f"- Real UR3e STEP (vendor geometry, as-supplied pose, inverted under the plate): {len(a['ur3e_real_step_collisions'])} pose collisions over the 9 states:")
        for s, n, v in a["ur3e_real_step_collisions"]:
            L.append(f"  - state {s}: {n} ({v} mm^3)")
        L.append("  These are pose-dependent (the STEP's elbow offset reaches +344/-223 mm in Y). They confirm the arm must run with UR safety planes/joint limits; the bolt-on hardware itself is clear.")
    L.append("")
v = json.load(open(os.path.join(R, "step_validation.json")))
L += ["## STEP re-import validation", "", f"{len(v)} STEP files re-imported (solid count + bbox) - errors: {sum('error' in x for x in v.values())}.", ""]
for k, x in v.items():
    if "/parts/" not in k:
        L.append(f"- {k}: {x.get('solids', x.get('solids_text_count'))} solids, {x['MB']} MB" + (f" - {x['note']}" if 'note' in x else ""))
open(os.path.join(R, "CHECKS.md"), "w").write("\n".join(L) + "\n")
print("ok")
